from datetime import date, timedelta


def _check_days(days):
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int, not %s" % type(days).__name__)


def _is_workday(d, holidays):
    return d.weekday() < 5 and d not in holidays


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    _check_days(days)
    holidays = frozenset(holidays)
    if days == 0:
        d = start
        while not _is_workday(d, holidays):
            d += timedelta(days=1)
        return d
    step = timedelta(days=1 if days > 0 else -1)
    remaining = abs(days)
    d = start
    while remaining:
        d += step
        if _is_workday(d, holidays):
            remaining -= 1
    return d


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)
    holidays = frozenset(holidays)
    count = 0
    d = first
    while d <= last:
        if _is_workday(d, holidays):
            count += 1
        d += timedelta(days=1)
    return count
